def link_old_handouts(apps, schema_editor):
    """كل اسم استلم عهدة قبل كده بقى صاحب عهدة، ولو اسمه زي حساب في النظام بيترب به"""
    Settlement = apps.get_model("trade", "CustodySettlement")
    Holder = apps.get_model("trade", "CustodyHolder")
    User = apps.get_model("auth", "User")
    users = {}
    for u in User.objects.all():
        full = f"{u.first_name} {u.last_name}".strip()
        for key in {u.username.strip().lower(), full.lower(), u.first_name.strip().lower()}:
            if key:
                users.setdefault(key, u)
    taken = set()
    for name in Settlement.objects.values_list("received_by", flat=True).distinct():
        clean = (name or "").strip()[:120] or "غير معروف"
        holder = Holder.objects.filter(name=clean).first()
        if holder is None:
            user = users.get(clean.lower())
            if user is not None and user.pk in taken:
                user = None
            holder = Holder.objects.create(name=clean, user=user)
            if user is not None:
                taken.add(user.pk)
        Settlement.objects.filter(received_by=name).update(holder=holder)


